motion:
/* hook: push on you; the fuel readout pulses on "eleven miles" */
tl.fromTo("#hookfig", { scale: 1.0, transformOrigin: "50% 60%" }, { scale: 1.07, duration: 7.4, ease: "none" }, 4.3);
tl.fromTo("#fuel11", { scale: 1 }, { scale: 1.12, duration: 0.3, yoyo: true, repeat: 1 }, 7.0);
/* the map: every road draws into one bridge, then the queue backs up it */
["#r1","#r2","#r3","#r4","#r5"].forEach((id, i) => tl.fromTo(id, { drawSVG: "0% 0%" }, { drawSVG: "0% 100%", duration: 0.9, ease: "power1.inOut" }, 12.6 + i * 0.25));
tl.fromTo("#queue", { drawSVG: "0% 0%" }, { drawSVG: "0% 100%", duration: 1.6, ease: "power1.out" }, 14.7);
/* rule 1 obeyed: the line ahead drifts under you */
tl.fromTo("#rail", { scale: 1.0, transformOrigin: "50% 55%" }, { scale: 1.08, duration: 4.5, ease: "none" }, 23.2);
/* the plant */
tl.fromTo("#radiobox", { scale: 0.98 }, { scale: 1.04, duration: 6.2, ease: "none" }, 28.2);
tl.fromTo("#staffbadge", { opacity: 0, y: 12 }, { opacity: 1, y: 0, duration: 0.3, ease: "power2.out" }, 31.6);
/* rule 2 obeyed: bridges counted, one by one */
[39.5, 39.8, 40.1, 40.4].forEach((t, i) => {
  tl.set("#brcount", { textContent: String(i + 1) }, t);
  tl.to(`#br${i}`, { opacity: 1, duration: 0.2 }, t);
});
/* good news: the cab window breathes */
tl.to("#cabwin", { boxShadow: "0 0 70px rgba(240,169,60,.6)", duration: 1.2, yoyo: true, repeat: 3, ease: "sine.inOut" }, 43.0);
/* bad news: one door */
tl.fromTo("#onedoor", { scale: 1 }, { scale: 1.1, duration: 0.3, yoyo: true, repeat: 1 }, 55.6);
/* inside: the key board, found */
tl.fromTo("#keyboard", { boxShadow: "0 0 0 0 rgba(240,169,60,0)" }, { boxShadow: "0 0 30px 6px rgba(240,169,60,.4)", duration: 0.8 }, 59.8);
/* the creak: light comes UP the stairs behind you */
tl.fromTo("#stairlight", { height: 0 }, { height: 220, duration: 1.8, ease: "power2.out" }, 62.0);
/* the voice */
tl.set("#drv", { textContent: "" }, 65.4);
tl.to("#drv", { duration: 1.0, scrambleText: { text: "DRIVER?", chars: "upperCase", speed: 0.7 } }, 65.6);
/* the recall */
tl.fromTo("#nodriver", { scale: 1.8, opacity: 0 }, { scale: 1, opacity: 1, duration: 0.32, ease: "power3.out" }, 77.0);
/* THE REVERSAL: the loop plays past where it ever has */
tl.to("#heremark", { opacity: 0.3, duration: 0.5, yoyo: true, repeat: 3 }, 80.0);
tl.to(".wb", { opacity: 1, duration: 0.12, stagger: 0.09, ease: "none" }, 81.6);
tl.fromTo("#warnword", { opacity: 0, scale: 1.4 }, { opacity: 1, scale: 1, duration: 0.35, ease: "power3.out" }, 85.8);
